598	        mat_free_VecDBL(pure_trans);
599	        pure_trans = NULL;
600	        return NULL;
601	    }
602	
603	    for (i = 0; i < num_pure_trans; i++) {
604	        mat_copy_vector_d3(ret_pure_trans->vec[i], pure_trans->vec[i]);
