707	/* Return spacegroup.number = 0 if failed */
708	static Spacegroup *get_spacegroup(int const hall_number,
709	                                  double const origin_shift[3],
710	                                  double const conv_lattice[3][3]) {
711	    Spacegroup *spacegroup;
712	    SpacegroupType spacegroup_type;
713	
714	    spacegroup = NULL;
715	
716	    if ((spacegroup = (Spacegroup *)malloc(sizeof(Spacegroup))) == NULL) {
717	        warning_memory("spacegroup");
718	        return NULL;
719	    }
720	
721	    if (-117 < hall_number && hall_number < 531 && hall_number != 0) {
722	        spacegroup_type = spgdb_get_spacegroup_type(hall_number);
723	        mat_copy_matrix_d3(spacegroup->bravais_lattice, conv_lattice);
724	        mat_copy_vector_d3(spacegroup->origin_shift, origin_shift);
725	        spacegroup->number = spacegroup_type.number;
726	        spacegroup->hall_number = hall_number;
727	        spacegroup->pointgroup_number = spacegroup_type.pointgroup_number;
728	        memcpy(spacegroup->schoenflies, spacegroup_type.schoenflies, 7);
729	        memcpy(spacegroup->hall_symbol, spacegroup_type.hall_symbol, 17);
730	        memcpy(spacegroup->international, spacegroup_type.international, 32);
731	        memcpy(spacegroup->international_long,
732	               spacegroup_type.international_full, 20);
733	        memcpy(spacegroup->international_short,
734	               spacegroup_type.international_short, 11);
735	        memcpy(spacegroup->choice, spacegroup_type.choice, 6);
736	    }
737	
738	    return spacegroup;
