741	/* Return 0 if failed */
742	static int iterative_search_hall_number(
743	    double origin_shift[3], double conv_lattice[3][3], int const candidates[],
744	    int const num_candidates, Primitive const *primitive,
745	    Symmetry const *symmetry, double const symprec,
746	    double const angle_tolerance) {
747	    int attempt, hall_number;
748	    double tolerance;
749	    Symmetry *sym_reduced;
750	
751	    debug_print("iterative_search_hall_number:\n");
752	
753	    hall_number = 0;
754	    sym_reduced = NULL;
755	
756	    hall_number =
757	        search_hall_number(origin_shift, conv_lattice, candidates,
758	                           num_candidates, primitive, symmetry, symprec);
759	
760	    if (hall_number != 0) {
761	        goto ret;
762	    }
763	
764	    tolerance = symprec;
765	    for (attempt = 0; attempt < NUM_ATTEMPT; attempt++) {
766	        debug_print("spglib: Attempt %d tolerance = %e failed", attempt,
767	                    tolerance);
768	
769	        tolerance *= REDUCE_RATE;
770	        sym_reduced = sym_reduce_operation(primitive->cell, symmetry, tolerance,
771	                                           angle_tolerance);
772	        if (sym_reduced) {
773	            hall_number = search_hall_number(origin_shift, conv_lattice,
774	                                             candidates, num_candidates,
775	                                             primitive, sym_reduced, symprec);
776	            sym_free_symmetry(sym_reduced);
777	            sym_reduced = NULL;
778	        }
779	        if (hall_number != 0) {
780	            break;
781	        }
782	    }
783	
784	ret:
785	    return hall_number;
786	}
