788	/* Return 0 if failed */
789	static int search_hall_number(double origin_shift[3], double conv_lattice[3][3],
790	                              int const candidates[], int const num_candidates,
791	                              Primitive const *primitive,
792	                              Symmetry const *symmetry, double const symprec) {
793	    int i, hall_number, aperiodic_axis;
794	    Centering centering;
795	    Pointgroup pointgroup;
796	    Symmetry *conv_symmetry;
797	    int tmat_int[3][3];
798	    double correction_mat[3][3], tmat[3][3], conv_lattice_tmp[3][3];
799	
800	    debug_print("search_hall_number:\n");
801	
802	    hall_number = 0;
803	    conv_symmetry = NULL;
804	
805	    aperiodic_axis = primitive->cell->aperiodic_axis;
806	
807	    /* primitive->cell->lattice is set right handed. */
808	    /* tmat_int is set right handed. */
809	
810	    /* For rhombohedral system, basis vectors for hP */
811	    /* (hexagonal lattice basis) are provided by tmat_int, */
