#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include "spglib.h"

static void build_lattice(double lattice[3][3], double const a, double const b,
                          double const c, double const al, double const be,
                          double const ga) {
    int i, j;
    double cx, cy, cz2, sg = sin(ga);
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++) lattice[i][j] = 0;
    lattice[0][0] = a;
    lattice[1][0] = b * cos(ga);
    lattice[1][1] = b * sg;
    cx = c * cos(be);
    cy = c * (cos(al) - cos(be) * cos(ga)) / sg;
    cz2 = c * c - cx * cx - cy * cy;
    lattice[2][0] = cx;
    lattice[2][1] = cy;
    lattice[2][2] = sqrt(cz2);
}

/* conv -> prim conjugation using C_mat */
static double X[3][3] = {{0.5, 0.5, 0}, {-0.5, 0.5, 0}, {0, 0, 1}};

int main(void) {
    static int rotations_raw[16][3][3];
    static double translations_raw[16][3];
    int num, n, i, j, k, uniq;
    int rot_u[16][3][3];
    double tra_u[16][3];
    double Xi[3][3] = {{1, 1, 0}, {-1, 1, 0}, {0, 0, 1}}; /* = inverse(X) rows? computed below */
    double lattice[3][3], prim_lat[3][3], tconv[3][3];
    double pi = 4 * atan(1.0);
    SpglibSpacegroupType out;

    num = spg_get_symmetry_from_database(rotations_raw, translations_raw, 14);
    printf("hall 14 db ops = %d\n", num);

    /* dedup modulo 1 (primitive setting) */
    uniq = 0;
    for (i = 0; i < num; i++) {
        double tt[3], rr[3][3], tmp[3][3];
        int dup = 0;
        /* rp = Xi * r * X ; tp = Xi * t*/
        for (j = 0; j < 3; j++)
            for (k = 0; k < 3; k++) rr[j][k] = rotations_raw[i][j][k];
        /* tmp = Xi*r */
        for (j = 0; j < 3; j++)
            for (k = 0; k < 3; k++) {
                tmp[j][k] = 0;
                for (int m = 0; m < 3; m++) tmp[j][k] += Xi[j][m] * rr[m][k];
            }
        /* rr = tmp*X */
        for (j = 0; j < 3; j++)
            for (k = 0; k < 3; k++) {
                rr[j][k] = 0;
                for (int m = 0; m < 3; m++) rr[j][k] += tmp[j][m] * X[m][k];
            }
        for (j = 0; j < 3; j++) {
            tt[j] = 0;
            for (int m = 0; m < 3; m++) tt[j] += Xi[j][m] * translations_raw[i][m];
            tt[j] -= floor(tt[j]);
        }
        for (n = 0; n < uniq; n++) {
            int same = 1;
            for (j = 0; j < 3; j++)
                for (k = 0; k < 3; k++)
                    if (rot_u[n][j][k] != (int)llround(rr[j][k])) same = 0;
            for (j = 0; j < 3; j++)
                if (fabs(tra_u[n][j] - tt[j]) > 1e-6) same = 0;
            if (same) dup = 1;
        }
        if (!dup) {
            for (j = 0; j < 3; j++) {
                for (k = 0; k < 3; k++) rot_u[uniq][j][k] = (int)llround(rr[j][k]);
                tra_u[uniq][j] = tt[j];
            }
            printf("op %d rot=(%d %d %d / %d %d %d / %d %d %d) t=(%.4f %.4f %.4f)\n",
                   uniq, rot_u[uniq][0][0], rot_u[uniq][0][1], rot_u[uniq][0][2],
                   rot_u[uniq][1][0], rot_u[uniq][1][1], rot_u[uniq][1][2],
                   rot_u[uniq][2][0], rot_u[uniq][2][1], rot_u[uniq][2][2],
                   tra_u[uniq][0], tra_u[uniq][1], tra_u[uniq][2]);
            uniq++;
        }
    }

    /* monoclinic lattice, b-unique */
    build_lattice(lattice, 5.2, 7.3, 6.4, 0, 109.0 * pi / 180, pi / 2);
    /* prim_lat = lat * X */
    for (j = 0; j < 3; j++)
        for (k = 0; k < 3; k++) {
            tconv[j][k] = 0;
            for (int m = 0; m < 3; m++) tconv[j][k] += lattice[j][m] * X[m][k];
        }
    for (j = 0; j < 3; j++)
        for (k = 0; k < 3; k++) prim_lat[j][k] = tconv[j][k];

    out = spg_get_spacegroup_type_from_symmetry(rot_u, tra_u, uniq, prim_lat, 0.01);
    printf("RESULT number=%d hall=%d (%s)\n", out.number, out.hall_number,
           out.international);
    return 0;
}
