def min_dist(lattice, positions):
    best = 1e9
    for i in range(len(positions)):
        for j in range(i + 1, len(positions)):
            d = [(positions[i][k] - positions[j][k] + 0.5) % 1.0 - 0.5 for k in range(3)]
            v = [sum(d[m] * lattice[m][k] for m in range(3)) for k in range(3)]
            best = min(best, math.sqrt(sum(x * x for x in v)))
    return best


