#include <math.h>
#include <stdio.h>
#include <stdlib.h>

#include "spglib.h"

/* SG 194 (P63/mmc): 24 ops, one generic site */
static void build_lattice(double lattice[3][3], double const a, double const b,
                          double const c, double const al, double const be,
                          double const ga) {
    int i, j;
    double cx, cy, cz2, sg = sin(ga);
    for (i = 0; i < 3; i++)
        for (j = 0; j < 3; j++) lattice[i][j] = 0;
    lattice[0][0] = a;
    lattice[1][0] = b * cos(ga);
    lattice[1][1] = b * sg;
    cx = c * cos(be);
    cy = c * (cos(al) - cos(be) * cos(ga)) / sg;
    cz2 = c * c - cx * cx - cy * cy;
    lattice[2][0] = cx;
    lattice[2][1] = cy;
    lattice[2][2] = sqrt(cz2);
}

int main(void) {
    static int rotations[64][3][3];
    static double translations[64][3];
    double lattice[3][3];
    static double position[64][3];
    static int types[64];
    int num, i, j, n;
    double pi = 4 * atan(1.0);
    SpglibDataset *ds;

    num = spg_get_symmetry_from_database(rotations, translations, 488);
    build_lattice(lattice, 2.456 * 3, 2.456 * 3, 6.696 * 3, pi / 2, pi / 2, 120.0 * pi / 180);
    n = 0;
    for (i = 0; i < num; i++) {
        double p[3], dup;
        int isdup = 0;
        for (j = 0; j < 3; j++) {
            p[j] = translations[i][j] +
                   rotations[i][j][0] * 0.137 + rotations[i][j][1] * 0.221 +
                   rotations[i][j][2] * 0.349;
            p[j] -= floor(p[j]);
        }
        for (int q = 0; q < n; q++) {
            dup = 1;
            for (j = 0; j < 3; j++) {
                double d = fabs(position[q][j] - p[j]);
                d -= floor(d);
                if (d > 1e-6) dup = 0;
            }
            if (dup) isdup = 1;
        }
        if (!isdup) {
            for (j = 0; j < 3; j++) position[n][j] = p[j];
            types[n] = 1;
            n++;
        }
    }
    printf("atoms = %d (ops in db = %d)\n", n, num);
    ds = spg_get_dataset(lattice, position, types, n, 0.01);
    if (ds) {
        printf("RESULT number=%d hall=%d international=%s n_ops=%d\n",
               ds->spacegroup_number, ds->hall_number, ds->international_symbol,
               ds->n_operations);
        spg_free_dataset(ds);
    } else {
        printf("RESULT failed\n");
    }
    return 0;
}
